<template><section class="container-main section-padding"><form class="pc-card mx-auto max-w-xl space-y-4" @submit.prevent="submit"><p class="pc-kicker">Supplier Workspace</p><h1 class="text-3xl font-bold text-white">Create a supplier account</h1><input v-model="form.full_name" class="input-field" required placeholder="Owner name"/><input v-model="form.email" class="input-field" type="email" required placeholder="Email"/><input v-model="form.phone" class="input-field" placeholder="Phone"/><input v-model="form.company_name" class="input-field" required placeholder="Supplier company"/><input v-model="form.country" class="input-field" placeholder="Country"/><input v-model="form.password" class="input-field" type="password" minlength="8" required placeholder="Password"/><p v-if="error" class="text-red-300">{{ error }}</p><button class="btn-primary w-full" :disabled="loading">{{ loading?'Creating...':'Create supplier account' }}</button></form></section></template>
<script setup lang="ts">definePageMeta({middleware:'guest'});const {register}=useAuth();const loading=ref(false);const error=ref('');const form=reactive({full_name:'',email:'',phone:'',company_name:'',country:'',password:'',role:'vendor',company_type:'supplier'});async function submit(){loading.value=true;try{await register(form);await navigateTo('/supplier-onboarding')}catch(e:any){error.value=e?.data?.detail||e?.message}finally{loading.value=false}}</script>
